export function getV1Key() {
  return ['v1'] as const
}

export function getV1AccountQueryKey(args: InferRequestType<typeof client.v1.account.$get>) {
  return ['v1', '/v1/account', args] as const
}

export function getV1AccountQueryOptions<
  TData = Awaited<
    ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.v1.account.$get>>>>
  >,
  TError = DefaultError,
>(args: InferRequestType<typeof client.v1.account.$get>, options?: ClientRequestOptions) {
  return queryOptions<
    Awaited<ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.v1.account.$get>>>>>,
    TError,
    TData,
    ReturnType<typeof getV1AccountQueryKey>
  >({
    queryKey: getV1AccountQueryKey(args),
    queryFn({ signal }) {
      return parseResponse(
        client.v1.account.$get(args, { ...options, init: { ...options?.init, signal } }),
      )
    },
  })
}

export function createV1Account<
  TData = Awaited<
    ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.v1.account.$get>>>>
  >,
  TError = DefaultError,
>(
  args: () => InferRequestType<typeof client.v1.account.$get>,
  options?: () => {
    query?: Omit<
      CreateQueryOptions<
        Awaited<
          ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.v1.account.$get>>>>
        >,
        TError,
        TData,
        ReturnType<typeof getV1AccountQueryKey>
      >,
      'queryKey' | 'queryFn'
    >
    options?: ClientRequestOptions
  },
  queryClient?: () => QueryClient,
) {
  return createQuery(() => {
    const { query, options: clientOptions } = options?.() ?? {}
    return { ...getV1AccountQueryOptions<TData, TError>(args(), clientOptions), ...query }
  }, queryClient)
}

